INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann der Entwurfsprozess ohne vorherige Anforderungsanalyse effektiv durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Anforderungen sind die Grundlage für den Entwurf"}, {"text": "Ja", "correct": false, "because": "Ohne Basis fehlt Orientierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Entwurfsprozess ausschließlich für die technische Umsetzung der Software verantwortlich?', 2, '[{"text": "Nein", "correct": true, "because": "Er umfasst auch Architektur und Planung"}, {"text": "Ja", "correct": false, "because": "Entwurf ist breiter gefasst"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Änderungen im Entwurfsprozess die Implementierungsphase erheblich beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Entwurf legt die Struktur fest"}, {"text": "Nein", "correct": false, "because": "Einfluss ist signifikant"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Entwurfsprozess abgeschlossen, sobald die Software implementiert wird?', 2, '[{"text": "Nein", "correct": true, "because": "Anpassungen können nötig sein"}, {"text": "Ja", "correct": false, "because": "Entwurf bleibt dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein schlechter Entwurfsprozess die Wartbarkeit der Software negativ beeinträchtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Unklare Struktur erschwert Wartung"}, {"text": "Nein", "correct": false, "because": "Wartbarkeit hängt vom Entwurf ab"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Element ist im Entwurfsprozess primär für die Struktur der Software verantwortlich?', 2, '[{"text": "Systemarchitektur", "correct": true, "because": "Definiert Aufbau und Komponenten"}, {"text": "Quellcode", "correct": false, "because": "Implementierungsphase"}, {"text": "Testplan", "correct": false, "because": "Testphase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aktivität im Entwurfsprozess hilft, die Interaktion zwischen Modulen zu definieren?', 3, '[{"text": "Schnittstellendesign", "correct": true, "because": "Legt Kommunikation fest"}, {"text": "Datenmodellierung", "correct": false, "because": "Fokus auf Datenstruktur"}, {"text": "Prototyping", "correct": false, "because": "Erste Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt der Entwurfsprozess hauptsächlich?', 2, '[{"text": "Technische Machbarkeit sicherstellen", "correct": true, "because": "Grundlage für Umsetzung"}, {"text": "Kosten minimieren", "correct": false, "because": "Sekundäres Ziel"}, {"text": "Benutzeroberfläche gestalten", "correct": false, "because": "Teilaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wird im Entwurfsprozess oft zur Visualisierung verwendet?', 2, '[{"text": "UML-Diagramme", "correct": true, "because": "Standard für Struktur und Ablauf"}, {"text": "Gantt-Diagramm", "correct": false, "because": "Zeitplanung"}, {"text": "Testskripte", "correct": false, "because": "Testphase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Entscheidung im Entwurfsprozess hat den größten Einfluss auf die Skalierbarkeit?', 2, '[{"text": "Architekturwahl", "correct": true, "because": "Bestimmt Erweiterbarkeit"}, {"text": "Datenbankdesign", "correct": false, "because": "Teilaspekt"}, {"text": "Programmiersprache", "correct": false, "because": "Sekundär"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aktivitäten gehören zum Entwurfsprozess?', 4, '[{"text": "Systemarchitektur definieren", "correct": true, "because": "Strukturplanung"}, {"text": "Schnittstellen spezifizieren", "correct": true, "because": "Kommunikation klären"}, {"text": "Code schreiben", "correct": false, "because": "Implementierung"}, {"text": "Datenmodelle erstellen", "correct": true, "because": "Datenstruktur festlegen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden im Entwurfsprozess berücksichtigt?', 3, '[{"text": "Leistungsanforderungen", "correct": true, "because": "Bestimmen Effizienz"}, {"text": "Sicherheitsaspekte", "correct": true, "because": "Schutz integrieren"}, {"text": "Marketingstrategie", "correct": false, "because": "Externer Bereich"}, {"text": "Skalierbarkeit", "correct": true, "because": "Zukunftssicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch einen unzureichenden Entwurfsprozess?', 3, '[{"text": "Technische Schulden", "correct": true, "because": "Schlechte Struktur kostet später"}, {"text": "Komplexe Wartung", "correct": true, "because": "Unklarheit erschwert"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Eher Verzögerung"}, {"text": "Inkompatibilitäten", "correct": true, "because": "Module passen nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein detaillierter Entwurfsprozess?', 4, '[{"text": "Klarheit für Entwickler", "correct": true, "because": "Richtung vorgegeben"}, {"text": "Reduzierte Fehlerquote", "correct": true, "because": "Planung minimiert Risiken"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Detailgrad bindet"}, {"text": "Bessere Testbarkeit", "correct": true, "because": "Struktur erleichtert Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen den Entwurfsprozess?', 3, '[{"text": "Modellierung mit UML", "correct": true, "because": "Visualisiert Struktur"}, {"text": "Prototyping", "correct": true, "because": "Testet Machbarkeit"}, {"text": "Code-Generierung", "correct": false, "because": "Implementierung"}, {"text": "Design Reviews", "correct": true, "because": "Qualitätssicherung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Entwurfsprozess kann parallel zur Implementierung laufen. b) Ein guter Entwurf eliminiert alle Fehler in der Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Parallel möglich, Fehler bleiben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Entwurfsprozess definiert nur die Benutzeroberfläche. b) UML-Diagramme verbessern die Kommunikation im Team.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Entwurf umfassender, UML hilfreich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein detaillierter Entwurfsprozess verlängert die Entwicklungszeit unnötig. b) Die Architekturwahl beeinflusst die Leistung der Software.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Detail hilft, Architektur entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Der Entwurfsprozess ist unabhängig von den Anforderungen. b) Prototyping im Entwurf hilft, Risiken zu minimieren.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Entwurf basiert auf Anforderungen, Prototyping nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein schlechter Entwurfsprozess führt zu höheren Wartungskosten. b) Der Entwurfsprozess ist nur für große Projekte relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten steigen, Entwurf immer wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

